        SDEX_BTC20_Pair3.flash(address(this), 0, Amount_SDEX_BTC20_Pair3, abi.encode(Amount_SDEX_BTC20_Pair3));

        (addrPath[0], addrPath[1]) = (address(BTC20), address(WETH));
